
(function(){
  "use strict";

  /* ============================================================
     1. 12 所 985 —— 由小到大，厦大最大（doge）
     ============================================================ */
  const LEVELS = [
    { key:'xjtu',  name:'西安交通大学',     color:'#14508f', r:15.0 },
    { key:'hit',   name:'哈尔滨工业大学',   color:'#1c5f9e', r:17.4 },
    { key:'buaa',  name:'北京航空航天大学', color:'#2f7fb8', r:20.2 },
    { key:'ruc',   name:'中国人民大学',     color:'#c0303a', r:23.4 },
    { key:'nju',   name:'南京大学',         color:'#5b2d83', r:27.1 },
    { key:'zju',   name:'浙江大学',         color:'#0b5ea8', r:31.4 },
    { key:'fudan', name:'复旦大学',         color:'#123f8c', r:36.4 },
    { key:'sjtu',  name:'上海交通大学',     color:'#a81c24', r:42.2 },
    { key:'ustc',  name:'中国科学技术大学', color:'#1b4a9c', r:49.2 },
    { key:'thu',   name:'清华大学',         color:'#6f2a86', r:57.6 },
    { key:'pku',   name:'北京大学',         color:'#7d1519', r:67.4 },
    { key:'xmu',   name:'厦门大学',         color:'#b8282f', r:78.8 }
  ];
  const MAX_LV = LEVELS.length - 1;

  // 整体尺寸系数（相对棋盘宽度，越大越难）
  const RS = 1.52;
  for (let i = 0; i < LEVELS.length; i++) LEVELS[i].r = +(LEVELS[i].r * RS).toFixed(1);

  /* 官方校徽：WebP 直接内嵌，无外部依赖、无同级目录要求 */
  const LOGO_DATA = [
    "data:image/webp;base64,",
    "data:image/webp;base64,",
    "data:image/webp;base64,",
    "data:image/webp;base64,",
    "data:image/webp;base64,",
    "data:image/webp;base64,",
    "data:image/webp;base64,",
    "data:image/webp;base64,",
    "data:image/webp;base64,",
    "data:image/webp;base64,",
    "data:image/webp;base64,",
    "data:image/webp;base64,"
  ]

  const emblemImgs = LOGO_DATA.map(function(src){
    const img = new Image();
    img.src = src;
    img.onload = function(){ if (typeof updateNextUI === 'function') updateNextUI(); };
    return img;
  });

  /* ============================================================
     2. 画布与尺寸
     ============================================================ */
  const W = 420, H = 640;
  const SPAWN_Y = 66;
  const DEATH_Y = 106;
  const G = 1900;
  // 碰撞手感：原来 REST 只有 0.08、切向摩擦 0.36，两颗球会互相“粘”住；
  // 现在提高弹性、降低切向摩擦，变成轻轻一碰就弹开。
  const REST = 0.52;         // 球与球：碰撞弹得更明显
  const REST_FLOOR = 0.34;   // 球与地面：能弹起，但不会一直乱跳
  const REST_WALL = 0.46;    // 球与两侧墙
  const FRICTION = 0.075;    // 切向摩擦
  const DANGER_TIME = 2.4;   // 稳定越线 2.4 秒才失败
  const DANGER_SPEED = 72;   // 仍在快速运动或弹跳时，不累计失败时间
  const HIT_FX_V = 150;      // 撞击超过这个相对法向速度才出小火花
  const PI2 = Math.PI * 2;

  // 合成冲击波：轻推附近的球，质量越小被推得越远
  const PUSH_R = 122;        // 波及半径
  const PUSH_MAX = 165;      // 单个球的最大速度增量
  const PUSH_REF_R = 46;     // 参考半径：比它小的推得更远，比它大的推得少

  const cvs = document.getElementById('game');
  const ctx = cvs.getContext('2d');
  const DPR = Math.min(window.devicePixelRatio || 1, 2);
  cvs.width = W * DPR;
  cvs.height = H * DPR;
  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);

  /* ============================================================
     3. 状态
     ============================================================ */
  const BEST_KEY = 'xmu-merge-best-v2';
  let balls = [];
  let particles = [];
  let shocks = [];
  let floats = [];
  let pending = [];
  let score = 0;
  let best = 0;
  try { best = parseInt(localStorage.getItem(BEST_KEY) || '0', 10) || 0; } catch(e){ best = 0; }
  let state = 'ready';           // ready | playing | over
  let cooldown = 0;
  let aimX = W / 2;
  let nextLevel = pickLevel();
  let lastT = 0;
  let acc = 0;
  let shake = 0;
  let touchAiming = false;

  /* ============================================================
     4. 音效
     ============================================================ */
  let ac = null, muted = false;
  function blip(freq, dur, type, gain){
    if (muted) return;
    try{
      if (!ac) ac = new (window.AudioContext || window.webkitAudioContext)();
      if (ac.state === 'suspended') ac.resume();
      const t = ac.currentTime;
      const o = ac.createOscillator(), g = ac.createGain();
      o.type = type || 'sine';
      o.frequency.setValueAtTime(freq, t);
      o.frequency.exponentialRampToValueAtTime(Math.max(60, freq * 0.72), t + (dur || 0.12));
      g.gain.setValueAtTime(0.0001, t);
      g.gain.linearRampToValueAtTime(gain || 0.05, t + 0.012);
      g.gain.exponentialRampToValueAtTime(0.0001, t + (dur || 0.12));
      o.connect(g); g.connect(ac.destination);
      o.start(t); o.stop(t + (dur || 0.12) + 0.03);
    }catch(e){}
  }

  /* ============================================================
     5. 工具
     ============================================================ */
  function pickLevel(){
    const weights = [35, 30, 20, 10, 5];
    let total = 0;
    for (let i = 0; i < weights.length; i++) total += weights[i];
    let r = Math.random() * total;
    for (let i = 0; i < weights.length; i++){
      r -= weights[i];
      if (r <= 0) return i;
    }
    return 0;
  }

  function makeBall(x, y, lv, vx, vy){
    const r = LEVELS[lv].r;
    return {
      x: x, y: y, vx: vx || 0, vy: vy || 0,
      r: r, m: r * r, level: lv,
      touched: false, danger: 0, appear: 0.16, dead: false, fx: 0
    };
  }

  function addScore(n, x, y){
    score += n;
    document.getElementById('score').textContent = score;
    if (score > best){
      best = score;
      document.getElementById('best').textContent = best;
      try { localStorage.setItem(BEST_KEY, String(best)); } catch(e){}
    }
    if (x !== undefined) floats.push({ x: x, y: y, text: '+' + n, life: 1 });
  }

  function burst(x, y, color, n){
    for (let i = 0; i < n; i++){
      const a = Math.random() * PI2;
      const sp = 60 + Math.random() * 200;
      particles.push({
        x: x, y: y,
        vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 40,
        r: 1.6 + Math.random() * 3.2, color: color, life: 1
      });
    }
  }

  // 撞击小火花：只是让“碰一下”有反馈，不参与物理
  function sparks(x, y, n, k){
    if (particles.length > 170) return;
    for (let i = 0; i < n; i++){
      const a = Math.random() * PI2;
      const sp = 40 + Math.random() * (70 + 120 * k);
      particles.push({
        x: x, y: y,
        vx: Math.cos(a) * sp, vy: Math.sin(a) * sp,
        r: 1.0 + Math.random() * 1.5,
        color: '#c98f2b',
        life: 0.5 + Math.random() * 0.3, spark: true
      });
    }
  }

  // 合成冲击波环
  function ring(x, y, rMax, color, alpha){
    shocks.push({ x: x, y: y, r: 6, rMax: rMax, life: 1, color: color, alpha: alpha });
  }

  // 合成爆炸：轻推附近的球，质量越小的被推得越远
  function pushWave(x, y, power, skip){
    for (let i = 0; i < balls.length; i++){
      const b = balls[i];
      if (b.dead || b === skip) continue;
      let dx = b.x - x, dy = b.y - y;
      const reach = PUSH_R + b.r;
      if (dx > reach || dx < -reach || dy > reach || dy < -reach) continue;
      let d = Math.sqrt(dx * dx + dy * dy);
      if (d > reach) continue;
      if (d < 0.5){ dx = 0; dy = -1; d = 1; }
      const gap = Math.max(0, d - b.r);          // 表面距离
      const f = 1 - Math.min(1, gap / PUSH_R);
      // 距离衰减改为 0.65 次幂：比原来的平方衰减更平缓，远处也能被推动。
      const fall = Math.pow(f, 0.65);
      // 冲量除以质量：m = r²，所以轻球加速多、重球加速少。
      // 限制质量倍率，避免最小球过猛、最大球几乎完全不动。
      const massFactor = Math.max(0.22, Math.min(2.6,
        (PUSH_REF_R * PUSH_REF_R) / b.m
      ));
      const dv = Math.min(PUSH_MAX, power * fall * massFactor);
      if (dv < 2) continue;
      b.vx += dx / d * dv;
      b.vy += dy / d * dv;
    }
  }

  let toastTimer = null;
  function toast(msg){
    const el = document.getElementById('toast');
    el.textContent = msg;
    el.classList.add('on');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function(){ el.classList.remove('on'); }, 1900);
  }

  function easeOutBack(t){
    const c1 = 1.70158, c3 = c1 + 1;
    return 1 + c3 * Math.pow(t - 1, 3) + c1 * Math.pow(t - 1, 2);
  }

  /* ============================================================
     6. 物理
     ============================================================ */
  function step(h){
    for (let i = 0; i < balls.length; i++){
      const b = balls[i];
      b.vy += G * h;
      b.vx *= 0.9992;
      b.x += b.vx * h;
      b.y += b.vy * h;

      if (b.x - b.r < 0){ b.x = b.r; if (b.vx < 0) b.vx = -b.vx * REST_WALL; }
      if (b.x + b.r > W){ b.x = W - b.r; if (b.vx > 0) b.vx = -b.vx * REST_WALL; }
      if (b.y + b.r > H){
        b.y = H - b.r;
        if (b.vy > 0) b.vy = -b.vy * REST_FLOOR;
        b.vx *= 0.94;
        b.touched = true;
      }
    }

    for (let i = 0; i < balls.length; i++){
      const a = balls[i];
      for (let j = i + 1; j < balls.length; j++){
        const b = balls[j];
        let dx = b.x - a.x, dy = b.y - a.y;
        const rs = a.r + b.r;
        if (dx > rs || dx < -rs || dy > rs || dy < -rs) continue;
        let d2 = dx * dx + dy * dy;
        if (d2 >= rs * rs) continue;
        let d = Math.sqrt(d2);
        if (d === 0){ d = 0.01; dx = 0.01; dy = 0; }

        const nx = dx / d, ny = dy / d;
        const overlap = rs - d;
        const ima = 1 / a.m, imb = 1 / b.m, tot = ima + imb;

        a.x -= nx * overlap * (ima / tot);
        a.y -= ny * overlap * (ima / tot);
        b.x += nx * overlap * (imb / tot);
        b.y += ny * overlap * (imb / tot);

        const rvx = b.vx - a.vx, rvy = b.vy - a.vy;
        const vn = rvx * nx + rvy * ny;
        if (vn < 0){
          const jn = -(1 + REST) * vn / tot;
          a.vx -= jn * nx * ima; a.vy -= jn * ny * ima;
          b.vx += jn * nx * imb; b.vy += jn * ny * imb;
          if (a.level !== b.level && vn < -45){
            const kick = Math.min(0.10, -vn / 6000);
            a.vx -= jn * nx * ima * kick; a.vy -= jn * ny * ima * kick;
            b.vx += jn * nx * imb * kick; b.vy += jn * ny * imb * kick;
          }

          const tx = -ny, ty = nx;
          const vt = rvx * tx + rvy * ty;
          const jt = (-vt / tot) * FRICTION;
          a.vx -= jt * tx * ima; a.vy -= jt * ty * ima;
          b.vx += jt * tx * imb; b.vy += jt * ty * imb;

          // 撞得够狠才冒几颗小火花（很轻，只是让碰撞有反馈）
          if (vn < -HIT_FX_V && a.fx <= 0 && b.fx <= 0 && a.level !== b.level){
            const k = Math.min(1, (-vn - HIT_FX_V) / 620);
            sparks(a.x + nx * a.r, a.y + ny * a.r, 2 + (k > 0.45 ? 2 : 0), k);
            a.fx = 0.11; b.fx = 0.11;
          }
        }

        a.touched = true;
        b.touched = true;

        if (a.level === b.level && !a.dead && !b.dead){
          let dup = false;
          for (let k = 0; k < pending.length; k++){
            if (pending[k][0] === a || pending[k][0] === b ||
                pending[k][1] === a || pending[k][1] === b){ dup = true; break; }
          }
          if (!dup) pending.push([a, b]);
        }
      }
    }

    if (pending.length) processMerges();
  }

  function processMerges(){
    for (let i = 0; i < pending.length; i++){
      const a = pending[i][0], b = pending[i][1];
      if (a.dead || b.dead) continue;
      a.dead = true; b.dead = true;

      const lv = a.level;
      const mx = (a.x + b.x) / 2;
      const my = (a.y + b.y) / 2;

      if (lv === MAX_LV){
        addScore(5000, mx, my);
        burst(mx, my, LEVELS[lv].color, 40);
        ring(mx, my, 150, '#d4a017', 0.65);
        pushWave(mx, my, 130);
        shake = 10;
        blip(660, 0.32, 'triangle', 0.09);
        setTimeout(function(){ blip(990, 0.4, 'triangle', 0.07); }, 110);
        toast('两所厦大合体，宇宙大爆炸 🎓');
        continue;
      }

      const nl = lv + 1;
      const nb = makeBall(mx, my, nl, (a.vx + b.vx) * 0.3, (a.vy + b.vy) * 0.3 - 34);
      nb.touched = a.touched || b.touched;
      nb.appear = 0.18;
      balls.push(nb);

      // 合成爆炸：轻推周围的球，球越小被推得越远（新球自己不吃自己的推力）
      pushWave(mx, my, 24 + nl * 7, nb);
      ring(mx, my, 26 + nl * 10, LEVELS[nl].color, 0.30 + nl * 0.02);

      addScore((nl + 1) * (nl + 2) * 5, mx, my);
      burst(mx, my, LEVELS[nl].color, 9 + nl * 2);
      blip(300 + nl * 44, 0.1, 'sine', 0.045);

      if (nl === MAX_LV){
        shake = 7;
        toast('🎓 恭喜合成厦门大学！');
        burst(mx, my, '#c9a227', 34);
        setTimeout(function(){ blip(880, 0.3, 'triangle', 0.08); }, 120);
      }
    }
    pending.length = 0;
    balls = balls.filter(function(b){ return !b.dead; });
  }

  /* ============================================================
     7. 更新
     ============================================================ */
  function update(dt){
    if (cooldown > 0) cooldown -= dt;

    if (state === 'playing'){
      acc += dt;
      const SUB = 1 / 240;
      let guard = 0;
      while (acc >= SUB && guard < 24){
        step(SUB);
        acc -= SUB;
        guard++;
      }
      if (guard >= 24) acc = 0;

      for (let i = 0; i < balls.length; i++){
        const b = balls[i];
        const aboveLine = b.touched && b.y - b.r < DEATH_Y;
        const nearlySettled = Math.hypot(b.vx, b.vy) < DANGER_SPEED;
        if (aboveLine && nearlySettled){
          b.danger += dt;
          if (b.danger > DANGER_TIME){ gameOver(); break; }
        } else if (b.danger > 0){
          // 弹回线下或仍在运动都会快速解除警报，不会“擦线就输”。
          b.danger = Math.max(0, b.danger - dt * 3.5);
        }
      }
    }

    for (let i = particles.length - 1; i >= 0; i--){
      const p = particles[i];
      if (p.spark){
        p.vy += 460 * dt;
        p.vx *= 0.93;
      } else {
        p.vy += 900 * dt;
        p.vx *= 0.985;
      }
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.life -= dt * (p.spark ? 3.2 : 1.7);
      if (p.life <= 0) particles.splice(i, 1);
    }
    for (let i = shocks.length - 1; i >= 0; i--){
      const s = shocks[i];
      s.r += (s.rMax - s.r) * Math.min(1, dt * 13);
      s.life -= dt * 2.6;
      if (s.life <= 0) shocks.splice(i, 1);
    }
    for (let i = floats.length - 1; i >= 0; i--){
      const f = floats[i];
      f.y -= 42 * dt;
      f.life -= dt * 1.25;
      if (f.life <= 0) floats.splice(i, 1);
    }
    if (shake > 0) shake = Math.max(0, shake - dt * 26);

    for (let i = 0; i < balls.length; i++){
      const b = balls[i];
      if (b.appear > 0) b.appear = Math.max(0, b.appear - dt);
      if (b.fx > 0) b.fx -= dt;
    }
  }

  /* ============================================================
     8. 绘制
     ============================================================ */
  // 一枚“校徽圆章”：白底 + 圆形裁切校徽 + 彩色外环
  function drawBadge(c, cx, cy, R, lv){
    c.save();
    c.translate(cx, cy);

    c.beginPath();
    c.arc(0, 0, R, 0, PI2);
    c.fillStyle = '#ffffff';
    c.fill();

    const img = emblemImgs[lv];
    const rc2 = R * 0.88;
    if (img && img.complete && img.naturalWidth > 0){
      const side = rc2 * 2 * 0.99;
      c.save();
      c.beginPath();
      c.arc(0, 0, rc2, 0, PI2);
      c.clip();
      c.drawImage(img, -side / 2, -side / 2, side, side);
      c.restore();
    } else {
      c.beginPath();
      c.arc(0, 0, rc2, 0, PI2);
      c.fillStyle = LEVELS[lv].color;
      c.fill();
    }

    const w = Math.max(1.6, R * 0.075);
    c.beginPath();
    c.arc(0, 0, R - w / 2, 0, PI2);
    c.lineWidth = w;
    c.strokeStyle = (lv === MAX_LV) ? '#d4a017' : LEVELS[lv].color;
    c.stroke();

    c.restore();
  }

  function drawBall(b){
    let s = 1;
    if (b.appear > 0){
      const dur = b.level === 0 ? 0.16 : 0.18;
      const k = 1 - b.appear / dur;
      s = 0.6 + 0.4 * easeOutBack(Math.max(0, Math.min(1, k)));
    }
    const r = b.r * s;

    ctx.save();
    ctx.beginPath();
    ctx.ellipse(b.x, b.y + b.r * 0.92, b.r * 0.78, b.r * 0.24, 0, 0, PI2);
    ctx.fillStyle = 'rgba(90,55,25,0.10)';
    ctx.fill();
    ctx.restore();

    drawBadge(ctx, b.x, b.y, r, b.level);

    // 高光
    ctx.save();
    ctx.beginPath();
    ctx.arc(b.x, b.y, r, 0, PI2);
    ctx.clip();
    const hg = ctx.createRadialGradient(
      b.x - r * 0.35, b.y - r * 0.45, r * 0.05,
      b.x - r * 0.3, b.y - r * 0.4, r * 1.5
    );
    hg.addColorStop(0, 'rgba(255,255,255,0.20)');
    hg.addColorStop(0.5, 'rgba(255,255,255,0)');
    hg.addColorStop(1, 'rgba(0,0,0,0.07)');
    ctx.fillStyle = hg;
    ctx.fillRect(b.x - r, b.y - r, r * 2, r * 2);
    ctx.restore();
  }

  function draw(){
    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
    ctx.clearRect(0, 0, W, H);

    const bg = ctx.createLinearGradient(0, 0, 0, H);
    bg.addColorStop(0, '#fffdf8');
    bg.addColorStop(0.55, '#fbf4e8');
    bg.addColorStop(1, '#f4e8d6');
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, W, H);

    const vg = ctx.createRadialGradient(W / 2, H * 0.42, 80, W / 2, H * 0.5, H * 0.72);
    vg.addColorStop(0, 'rgba(164,38,44,0.03)');
    vg.addColorStop(1, 'rgba(120,70,20,0.09)');
    ctx.fillStyle = vg;
    ctx.fillRect(0, 0, W, H);

    ctx.save();
    if (shake > 0) ctx.translate((Math.random() - 0.5) * shake, (Math.random() - 0.5) * shake);

    // 警戒线
    let dmax = 0;
    for (let i = 0; i < balls.length; i++) if (balls[i].danger > dmax) dmax = balls[i].danger;
    const warn = Math.min(1, dmax / DANGER_TIME);
    const pulse = warn > 0.05 ? 0.6 + 0.4 * Math.sin(Date.now() / 110) : 0;

    ctx.save();
    ctx.setLineDash([7, 7]);
    ctx.lineWidth = 1.6 + warn * 1.6;
    ctx.strokeStyle = 'rgba(164,38,44,' + (0.28 + warn * 0.62 * (0.55 + 0.45 * pulse)).toFixed(3) + ')';
    if (warn > 0.2){ ctx.shadowColor = 'rgba(184,40,47,0.55)'; ctx.shadowBlur = 10 * warn; }
    ctx.beginPath();
    ctx.moveTo(12, DEATH_Y);
    ctx.lineTo(W - 12, DEATH_Y);
    ctx.stroke();
    ctx.restore();

    ctx.save();
    ctx.font = '600 9.5px "PingFang SC","Microsoft YaHei",sans-serif';
    ctx.fillStyle = 'rgba(164,38,44,' + (0.42 + warn * 0.5).toFixed(2) + ')';
    ctx.textAlign = 'right';
    ctx.fillText('警戒线', W - 14, DEATH_Y - 6);
    ctx.restore();

    // 投放辅助
    if (state === 'playing' && cooldown <= 0){
      const r = LEVELS[nextLevel].r;
      const x = Math.min(Math.max(aimX, r + 2), W - r - 2);
      ctx.save();
      ctx.setLineDash([5, 8]);
      ctx.lineWidth = 1.4;
      ctx.strokeStyle = 'rgba(120,90,60,0.24)';
      ctx.beginPath();
      ctx.moveTo(x, SPAWN_Y + r + 6);
      ctx.lineTo(x, H - 8);
      ctx.stroke();
      ctx.restore();

      ctx.save();
      ctx.globalAlpha = 0.36;
      drawBadge(ctx, x, SPAWN_Y, r, nextLevel);
      ctx.restore();
    }

    for (let i = 0; i < balls.length; i++) drawBall(balls[i]);

    // 合成冲击波环
    for (let i = 0; i < shocks.length; i++){
      const s = shocks[i];
      ctx.save();
      ctx.globalAlpha = Math.max(0, s.life) * s.alpha;
      ctx.strokeStyle = s.color;
      ctx.lineWidth = 1.2 + 2.4 * s.life;
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.r, 0, PI2);
      ctx.stroke();
      ctx.restore();
    }

    for (let i = 0; i < particles.length; i++){
      const p = particles[i];
      ctx.save();
      ctx.globalAlpha = Math.max(0, p.life);
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.r * p.life, 0, PI2);
      ctx.fill();
      ctx.restore();
    }

    for (let i = 0; i < floats.length; i++){
      const f = floats[i];
      ctx.save();
      ctx.globalAlpha = Math.max(0, Math.min(1, f.life * 1.6));
      ctx.font = '800 15px "PingFang SC","Microsoft YaHei",sans-serif';
      ctx.textAlign = 'center';
      ctx.fillStyle = '#b8282f';
      ctx.shadowColor = 'rgba(255,255,255,0.9)';
      ctx.shadowBlur = 5;
      ctx.fillText(f.text, f.x, f.y - (1 - f.life) * 24);
      ctx.restore();
    }

    ctx.restore();

    const lg = ctx.createLinearGradient(0, 0, 7, 0);
    lg.addColorStop(0, 'rgba(140,90,50,0.16)');
    lg.addColorStop(1, 'rgba(140,90,50,0)');
    ctx.fillStyle = lg;
    ctx.fillRect(0, 0, 7, H);
    const rg = ctx.createLinearGradient(W, 0, W - 7, 0);
    rg.addColorStop(0, 'rgba(140,90,50,0.16)');
    rg.addColorStop(1, 'rgba(140,90,50,0)');
    ctx.fillStyle = rg;
    ctx.fillRect(W - 7, 0, 7, H);
  }

  /* ============================================================
     9. 主循环
     ============================================================ */
  function loop(t){
    if (!lastT) lastT = t;
    let dt = (t - lastT) / 1000;
    lastT = t;
    if (dt > 0.05) dt = 0.05;
    update(dt);
    draw();
    requestAnimationFrame(loop);
  }

  /* ============================================================
     10. 交互（鼠标点一下 / 触屏按住拖动松手投放）
     ============================================================ */
  function pointerX(clientX){
    const rect = cvs.getBoundingClientRect();
    return (clientX - rect.left) * (W / rect.width);
  }

  cvs.addEventListener('pointermove', function(e){
    if (e.pointerType === 'mouse') aimX = pointerX(e.clientX);
    else if (touchAiming) aimX = pointerX(e.clientX);
  }, { passive: true });

  cvs.addEventListener('pointerdown', function(e){
    e.preventDefault();
    if (state !== 'playing') return;
    aimX = pointerX(e.clientX);
    if (e.pointerType === 'mouse'){
      drop();                       // 鼠标：点一下就投
    } else {
      touchAiming = true;           // 触屏：按下先瞄准，松手才投
    }
  });

  cvs.addEventListener('pointerup', function(e){
    if (!touchAiming) return;
    touchAiming = false;
    if (state !== 'playing') return;
    aimX = pointerX(e.clientX);
    drop();
  });

  cvs.addEventListener('pointercancel', function(){ touchAiming = false; });
  cvs.addEventListener('contextmenu', function(e){ e.preventDefault(); });

  function drop(){
    if (state !== 'playing' || cooldown > 0) return;
    const lv = nextLevel;
    const r = LEVELS[lv].r;
    const x = Math.min(Math.max(aimX, r + 2), W - r - 2);
    balls.push(makeBall(x, SPAWN_Y, lv, 0, 30));
    nextLevel = pickLevel();
    cooldown = 0.4;
    updateNextUI();
    blip(220, 0.07, 'sine', 0.03);
  }

  /* ============================================================
     11. 界面
     ============================================================ */
  const nextCvs = document.getElementById('next');
  const nextCtx = nextCvs.getContext('2d');
  const nextDpr = Math.min(window.devicePixelRatio || 1, 2);
  nextCvs.width = 80 * nextDpr;
  nextCvs.height = 80 * nextDpr;
  nextCtx.setTransform(nextDpr, 0, 0, nextDpr, 0, 0);

  function updateNextUI(){
    nextCtx.setTransform(nextDpr, 0, 0, nextDpr, 0, 0);
    nextCtx.clearRect(0, 0, 80, 80);
    drawBadge(nextCtx, 40, 40, 35, nextLevel);
    document.getElementById('nextName').textContent = LEVELS[nextLevel].name;
  }

  // 校徽图谱：由小到大一条（按累计宽度排版，互不重叠）
  function buildChain(){
    const cc = document.getElementById('chaincvs');
    if (!cc) return;
    const cctx = cc.getContext('2d');
    const CW = 400, CH = 58;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    cc.width = CW * dpr;
    cc.height = CH * dpr;
    cctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    cctx.clearRect(0, 0, CW, CH);

    const n = LEVELS.length;
    const gap = 3;
    const radii = [];
    for (let i = 0; i < n; i++) radii.push(6.4 + i * 1.5);
    let need = gap * (n - 1);
    for (let i = 0; i < n; i++) need += radii[i] * 2;
    const k = Math.min(1, (CW - 14) / need);
    let x = (CW - need * k) / 2;
    const base = CH - 4;
    for (let i = 0; i < n; i++){
      const r = radii[i] * k;
      drawBadge(cctx, x + r, base - r, r, i);
      x += r * 2 + gap * k;
    }
  }

  function showOverlay(title, text, btnText, scoreHTML){
    const ov = document.getElementById('overlay');
    document.getElementById('ovTitle').textContent = title;
    document.getElementById('ovText').innerHTML = text;
    document.getElementById('ovBtn').textContent = btnText;
    const sc = document.getElementById('ovScore');
    if (scoreHTML){ sc.innerHTML = scoreHTML; sc.style.display = 'block'; }
    else sc.style.display = 'none';
    ov.classList.remove('hide');
  }

  function hideOverlay(){
    document.getElementById('overlay').classList.add('hide');
  }

  function gameOver(){
    if (state !== 'playing') return;
    state = 'over';
    blip(180, 0.35, 'sawtooth', 0.05);
    setTimeout(function(){ blip(120, 0.5, 'sawtooth', 0.05); }, 160);
    showOverlay(
      '装不下了',
      '校徽稳定堆过警戒线太久<br>弹跳过线不会失败，再来一局吧',
      '再来一局',
      '<small>本局得分</small>' + score
    );
  }

  function reset(){
    balls = [];
    particles = [];
    shocks = [];
    floats = [];
    pending = [];
    score = 0;
    cooldown = 0;
    acc = 0;
    shake = 0;
    touchAiming = false;
    document.getElementById('score').textContent = '0';
    document.getElementById('best').textContent = best;
    nextLevel = pickLevel();
    updateNextUI();
    state = 'playing';
    hideOverlay();
  }

  document.getElementById('ovBtn').addEventListener('click', function(){
    if (state === 'over') reset();
    else { state = 'playing'; hideOverlay(); }
    blip(520, 0.09, 'sine', 0.04);
  });

  document.getElementById('restart').addEventListener('click', reset);

  const muteBtn = document.getElementById('mute');
  muteBtn.addEventListener('click', function(){
    muted = !muted;
    muteBtn.textContent = muted ? '🔇 音效关' : '🔊 音效开';
    if (!muted) blip(700, 0.08, 'sine', 0.04);
  });

  window.addEventListener('keydown', function(e){
    if (e.code === 'Space'){ e.preventDefault(); if (state === 'playing') drop(); }
    if (e.key === 'r' || e.key === 'R') reset();
  });

  // 手机：阻止下拉刷新 / 双指缩放
  document.addEventListener('gesturestart', function(e){ e.preventDefault(); });
  document.addEventListener('touchmove', function(e){
    if (e.target === cvs) e.preventDefault();
  }, { passive: false });

  /* ============================================================
     12. 启动
     ============================================================ */
  document.getElementById('best').textContent = best;
  buildChain();
  updateNextUI();
  showOverlay(
    '合成厦门大学',
    '移动选择落点，点击投放<br>碰撞会回弹，稳定堆过警戒线才会结束',
    '开始合成'
  );
  requestAnimationFrame(loop);

  // 调试钩子：__xmuDebug().balls
  window.__xmuDebug = function(){
    return {
      balls: balls, particles: particles, shocks: shocks, pending: pending,
      score: score, state: state, nextLevel: nextLevel, levels: LEVELS,
      pushWave: pushWave, push: { R: PUSH_R, MAX: PUSH_MAX, REF_R: PUSH_REF_R }
    };
  };

  window.addEventListener('load', function(){ updateNextUI(); buildChain(); });
})();
